import{_ as d,o,c as r,ag as e}from"./chunks/framework.C9sp7nFj.js";const M=JSON.parse('{"title":"MovMSSyncOn 主从协同运动","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/21. 主从运动指令/MovMSSyncOn.md","filePath":"3. 指令/21. 主从运动指令/MovMSSyncOn.md","lastUpdated":1778862643000}'),a={name:"3. 指令/21. 主从运动指令/MovMSSyncOn.md"};function S(n,t,l,i,c,s){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="movmssyncon-主从协同运动" tabindex="-1">MovMSSyncOn 主从协同运动 <a class="header-anchor" href="#movmssyncon-主从协同运动" aria-label="Permalink to &quot;MovMSSyncOn 主从协同运动&quot;">​</a></h1><p>该指令用于使主从机器人进入到协同状态，并以设定的速度运动到目标位置。与 MovJ 指令类似，在执行完该指令时可以附加进行 IO 操作。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>MovMSSyncOn([MSGroup], SyncId, P, [V], [Tool], [Coord], [PayLoad], [DO]) MovMSSyncOn([主从组], 协同标识, 目标位置, [目标速度], [工具参数], [坐标系参数], [工件负载], [IO操作])</p><p><em>(备注：带 [] 参数为可选参数)</em></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>[MSGroup]</td><td>enum</td><td>机器人协同运动时的主从组参数，用于在多机协同过程中区分所启用的机器人协同方式。详见下方 MSGroup 取值说明。</td><td>DEFAULT（仅限从机器人选择）</td></tr><tr><td>SyncId</td><td>SYNCID 变量</td><td>机器人协同标识 ID 号，用于本机与协同机器人之间进行协同校验，主从机器人 ID 一致时才为有效协同。</td><td></td></tr><tr><td>P</td><td>APOS 或 CPOS 变量</td><td>坐标系下的目标点位置。</td><td></td></tr><tr><td>[V]</td><td>SPEED 变量</td><td>指定机器人执行 MovMSSyncOn 指令时的速度，包括机器人末端的平移速度、旋转速度以及外部轴的移动速度等。SPEED 变量中的 tcp、ori 分量有效；有外部轴时，exj_l、exj_r 分量有效。</td><td>V4000</td></tr><tr><td>[Tool]</td><td>TOOL 变量</td><td>机器人执行该轨迹时使用的工具参数。</td><td>当前系统中设置的工具参数</td></tr><tr><td>[Coord]</td><td>USERCOOR 变量</td><td>机器人执行该轨迹时使用的用户坐标系。</td><td>当前系统中设置的坐标系参数</td></tr><tr><td>[PayLoad]</td><td>PAYLOAD 变量</td><td>机器人执行该轨迹时使用的工件负载参数。</td><td>当前系统中设置的负载参数</td></tr><tr><td>[DO]</td><td>string</td><td>机器人执行完该指令后可触发的 IO 操作。支持 SetDO、SetAO、SetSimDO、SetSimAO、PulseOut、PulseSimOut、SetDO8421、SetSimDO8421、SetDIEdge、SetSimDIEdge 等指令。</td><td>NULL（无任何操作）</td></tr></tbody></table><blockquote><p><strong>MSGroup 取值说明</strong>：</p><ul><li>MSGroup1：第一组主从组参数，仅限主机器人选择</li><li>MSGroup2：第二组主从组参数，仅限主机器人选择</li><li>MSGroup3：第三组主从组参数，仅限主机器人选择</li><li>MSGroup4：第四组主从组参数，仅限主机器人选择</li><li>MSGroup5：第五组主从组参数，仅限主机器人选择</li><li>MSGroup6：第六组主从组参数，仅限主机器人选择</li><li>MSGroup7：第七组主从组参数，仅限主机器人选择</li><li>DEFAULT：缺省类型，仅限从机器人选择</li></ul></blockquote>',9)])])}const u=d(a,[["render",S]]);export{M as __pageData,u as default};
